        "text": "Уяви пасажира у вагоні. Його швидкість відносно землі дорівнює векторній сумі швидкості вагона та швидкості відносно вагона. Це співвідношення для систем із паралельними осями, які не обертаються. Якщо вагон рухається зі сталою швидкістю, прискорення в обох системах однакове. Якщо швидкість вагона змінюється, прискорення вже не збігаються. Штрих у позначенні рухомої системи відліку не є знаком похідної. На іспиті важливо назвати умови, за яких перетворення застосовне."
