    "source": "За наданою розшифровкою та вибірково звіреними кадрами лекції. Таймкоди орієнтовні; математичні записи нормалізовано. Блоки «З нуля», задачі, тести й питання іспиту — авторські навчальні доповнення, не офіційні білети. Розширено переказ усних пояснень за таймкодами; додаткові математичні уточнення не є дослівними висловами викладача. Акценти лектора — переказ за попереднім конспектом, не дослівні цитати. Нові задачі: адаптовані умови зі збірника С. О. Подласова (2023), розв’язання та схеми підготовлено окремо.",
