        "text": "Для двох вантажів, з’єднаних нерозтяжною ниткою, модулі прискорень однакові, але напрями можуть бути різними. Натяг уздовж однієї ідеальної нитки однаковий. На похилій площині зручно обрати вісь вздовж поверхні та вісь перпендикулярно. Сила тертя спокою протидіє можливому ковзанню і не завжди дорівнює максимальному значенню. На межі руху вона досягає коефіцієнта тертя, помноженого на реакцію опори. На захисті поясни, чому напрям тертя залежить від того, в який бік вантаж намагається рушити."
